import{_ as a,o as n,c as e,K as l}from"./chunks/framework.b785766f.js";const u=JSON.parse('{"title":"github pages/hexo搭建精致博客","description":"","frontmatter":{"title":"github pages/hexo搭建精致博客","date":"2017-12-20T00:00:00.000Z","aside":true,"tags":["hexo"]},"headers":[],"relativePath":"posts/2017/121801.md","filePath":"posts/2017/121801.md","lastUpdated":1677951145000}'),p={name:"posts/2017/121801.md"};function t(i,s,r,o,c,b){return n(),e("div",null,[...s[0]||(s[0]=[l(`<blockquote><p>由于 hexo 是基于 node 的框架，所以关于 web 前端的知识我不会讲太细，如果你是 python 工程师、ruby 工程师，都有其对应的框架，简化搭建博客的难度，不用在 hexo 上过分用心. 因为直到现在我才明白，我花费了很多心思搞服务器、弄域名、学后台语言，为的是自己搞一个网站，然而却忽略了最为重要的是<strong>内容</strong>。</p></blockquote><h2 id="安装-node-环境" tabindex="-1">安装 node 环境 <a class="header-anchor" href="#安装-node-环境" aria-label="Permalink to &quot;安装 node 环境&quot;">​</a></h2><p>请移步 <a href="http://nodejs.cn/" target="_blank" rel="noreferrer">nodeJS 中文网</a></p><h2 id="安装-git" tabindex="-1">安装 git <a class="header-anchor" href="#安装-git" aria-label="Permalink to &quot;安装 git&quot;">​</a></h2><p>请移步 <a href="https://git-scm.com/book/zh/v1/%E8%B5%B7%E6%AD%A5-%E5%AE%89%E8%A3%85-Git" target="_blank" rel="noreferrer">起步 - 安装 Git</a></p><h2 id="全局安装-hexo-并初始化一个工程" tabindex="-1">全局安装 hexo 并初始化一个工程 <a class="header-anchor" href="#全局安装-hexo-并初始化一个工程" aria-label="Permalink to &quot;全局安装 hexo 并初始化一个工程&quot;">​</a></h2><p>过程与安装大部分脚手架工具一样类似，工具可以使用命令行工具或 git bash</p><ol><li>全局安装 hexo<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">$ npm install hexo-cli -g</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li>进入一个文件夹（你想把工程放到哪个文件夹就进入哪个文件夹，我的是 <code>D:/files/hexo</code> ），初始化一个工程<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">$ hexo init yourProjectName</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li>进入你的工程，安装需要的资源<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">$ cd blog</span></span>
<span class="line"><span style="color:#babed8;">$ npm install</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li>启动你的工程，默认监听 4000 端口，打开 <code>localhost:4000</code> 便可以访问到<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">$ hexo server</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li>常用的命令就四个 <ul><li>hexo clean 清空缓存</li><li>hexo generate 简写 hexo g，生成静态文件</li><li>hexo serve 简写 hexo s，启动一个服务，将本地静态文件可视化</li><li>hexo deploy 简写 hexo d，发布</li></ul></li></ol><p>这时候一个最原始的 hexo 博客就搭建好了。</p><h2 id="安装主题" tabindex="-1">安装主题 <a class="header-anchor" href="#安装主题" aria-label="Permalink to &quot;安装主题&quot;">​</a></h2><p>可以去官方主题库区找，也可以去百度一下信誉比较好的主题，这个根据自己的喜好选择就行。</p><ol><li>安装。主题一般都是托管在 GitHub，可以直接将主题直接 clone 到你的工程下的 themes 文件夹下，也可以下载压缩包解压到 themes 文件夹下。</li><li>配置。打开_config.yml（主题文件夹内还有一个_config.yml，不要弄混）文件进行设置，比如你安装好的主题的文件夹叫 themeABC，那就将 theme 设置为 themeABC</li></ol><h2 id="发布到自己的-github-pages" tabindex="-1">发布到自己的 GitHub pages <a class="header-anchor" href="#发布到自己的-github-pages" aria-label="Permalink to &quot;发布到自己的 GitHub pages&quot;">​</a></h2><p>pages 分两种，一种是对应自己的 GitHub 账号，一种对应 GitHub 上的一个工程，现在我们讲的是对应自己 GitHub 账号的那种。</p><ol><li>创建。创建一个工程，格式为 <code>nickname.github.io</code> ，我的 GitHub 昵称叫做 recoluan，所以我的 pages 名字叫做 <code>recoluan.github.io</code></li><li>配置。打开_config.yml，配置自己的工程。<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">deploy:</span></span>
<span class="line"><span style="color:#babed8;">  type: git</span></span>
<span class="line"><span style="color:#babed8;">  repo: git@github.com:recoluan/recoluan.github.io.git</span></span>
<span class="line"><span style="color:#babed8;">  branch: master</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div></li><li>在你的本体工程下使用命令行工具发布到 GitHub 工程，并使用 nickname.github.io 访问。<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">$ hexo g</span></span>
<span class="line"><span style="color:#babed8;">$ hexo d</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li></ol><h2 id="绑定域名" tabindex="-1">绑定域名 <a class="header-anchor" href="#绑定域名" aria-label="Permalink to &quot;绑定域名&quot;">​</a></h2><ol><li>解析域名。在你的域名服务平台的控制台进行解析，设置两条记录，记录的类型都选择 CNAME，记录值都选择 nickname.github.io ，主机记录一条为空，另一条填写 www。</li><li>设置 pages。在 github 上打开你的工程，点击 Settings ，然后找到 GitHub Pages 下的 Custom domain ，填写你的 www 域名，点击 save 保存，这时域名就可以访问到你的网站了。</li><li>修复本地工程。GitHub 工程里会出现一个 CNAME 文件里面写着你域名，见这个文件放到你的本地工程的所用主题下的 source 文件夹下，不然下次发布时会清空这个文件。</li></ol><h2 id="使用-gitment-添加评论功能" tabindex="-1">使用 gitment 添加评论功能 <a class="header-anchor" href="#使用-gitment-添加评论功能" aria-label="Permalink to &quot;使用 gitment 添加评论功能&quot;">​</a></h2><ol><li>注册 OAuth Apps。代开你的 GitHub 的设置，然后在左边菜单栏最下方找到 Developer settings 选项，点击进去找到 OAuth Apps，添加新的账号，其中“Application name”对应的你的 Pages 地址，我的是 <code>recoluan.github.io</code> ,“Homepage URL”和“Authorization callback URL”对应的是域名，我的是 <code>http://www.recoluan.com</code> ,这样会生成 client_id 和 client_secret。</li><li>配置_config.yml。<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">gitment:</span></span>
<span class="line"><span style="color:#babed8;">  enable: true</span></span>
<span class="line"><span style="color:#babed8;">  owner: recoluan</span></span>
<span class="line"><span style="color:#babed8;">  repo: recoluan.github.io</span></span>
<span class="line"><span style="color:#babed8;">  client_id: your client_id</span></span>
<span class="line"><span style="color:#babed8;">  client_secret: your client_secret</span></span>
<span class="line"><span style="color:#babed8;">  perPage: 10</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div></li><li>将前端代码放到文章页或者专门的评论页<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">&lt;% if(theme.gitment.enable &amp;&amp; is_post()) { %&gt;</span></span>
<span class="line"><span style="color:#babed8;">    &lt;script type=&quot;text/javascript&quot; src=&quot;https://imsun.github.io/gitment/dist/gitment.browser.js&quot;&gt;&lt;/script&gt;</span></span>
<span class="line"><span style="color:#babed8;">    &lt;script&gt;</span></span>
<span class="line"><span style="color:#babed8;">    var gitment = new Gitment({</span></span>
<span class="line"><span style="color:#babed8;">        id: window.location.pathname,</span></span>
<span class="line"><span style="color:#babed8;">        owner:&quot;&lt;%= theme.gitment.owner%&gt;&quot;,</span></span>
<span class="line"><span style="color:#babed8;">        repo:&quot;&lt;%= theme.gitment.repo%&gt;&quot;,</span></span>
<span class="line"><span style="color:#babed8;">        oauth: {</span></span>
<span class="line"><span style="color:#babed8;">          client_id:&quot;&lt;%= theme.gitment.client_id%&gt;&quot;,</span></span>
<span class="line"><span style="color:#babed8;">          client_secret:&quot;&lt;%= theme.gitment.client_secret%&gt;&quot;</span></span>
<span class="line"><span style="color:#babed8;">        },</span></span>
<span class="line"><span style="color:#babed8;">        perPage:&quot;&lt;%= theme.gitment.perPage%&gt;&quot;,</span></span>
<span class="line"><span style="color:#babed8;">    });</span></span>
<span class="line"><span style="color:#babed8;">    gitment.render(&#39;comments&#39;);</span></span>
<span class="line"><span style="color:#babed8;">    &lt;/script&gt;</span></span>
<span class="line"><span style="color:#babed8;">&lt;% } else { %&gt;</span></span>
<span class="line"><span style="color:#babed8;">   &lt;p&gt;评论系统未开启，无法评论！&lt;/p&gt;</span></span>
<span class="line"><span style="color:#babed8;">&lt;%}%&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div></li></ol><h2 id="jsoncontent-配置" tabindex="-1">jsonContent 配置 <a class="header-anchor" href="#jsoncontent-配置" aria-label="Permalink to &quot;jsonContent 配置&quot;">​</a></h2><ol><li><p>首先安装 hexo-generator-json-content</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">hexo-generator-json-content</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>然后在当前主题中的 <code>_config.yml</code> 中配置</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">## 搜索</span></span>
<span class="line"><span style="color:#babed8;">jsonContent:</span></span>
<span class="line"><span style="color:#babed8;">  searchLocal: true</span></span>
<span class="line"><span style="color:#babed8;">  searchGoogle: false</span></span>
<span class="line"><span style="color:#babed8;">  meta: false</span></span>
<span class="line"><span style="color:#babed8;">  pages: false</span></span>
<span class="line"><span style="color:#babed8;">  posts:</span></span>
<span class="line"><span style="color:#babed8;">    title: true</span></span>
<span class="line"><span style="color:#babed8;">    date: true</span></span>
<span class="line"><span style="color:#babed8;">    path: true</span></span>
<span class="line"><span style="color:#babed8;">    text: true</span></span>
<span class="line"><span style="color:#babed8;">    raw: false</span></span>
<span class="line"><span style="color:#babed8;">    content: false</span></span>
<span class="line"><span style="color:#babed8;">    slug: false</span></span>
<span class="line"><span style="color:#babed8;">    updated: false</span></span>
<span class="line"><span style="color:#babed8;">    comments: false</span></span>
<span class="line"><span style="color:#babed8;">    link: false</span></span>
<span class="line"><span style="color:#babed8;">    permalink: false</span></span>
<span class="line"><span style="color:#babed8;">    excerpt: false</span></span>
<span class="line"><span style="color:#babed8;">    categories: false</span></span>
<span class="line"><span style="color:#babed8;">    tags: true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br></div></div></li></ol><h2 id="设置-banner-图" tabindex="-1">设置 banner 图 <a class="header-anchor" href="#设置-banner-图" aria-label="Permalink to &quot;设置 banner 图&quot;">​</a></h2><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#babed8;">banner:</span></span>
<span class="line"><span style="color:#babed8;">    img: /img/banner.jpg</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这里注意，<code>/</code>代表的是根目录，项目会去根目录去寻找，否则会自动在当前目录为基础寻找。</p><p>转自博客：<a href="http://recoluan.gitlab.io" target="_blank" rel="noreferrer"><strong>午后南杂</strong></a></p>`,25)])])}const m=a(p,[["render",t]]);export{u as __pageData,m as default};
